import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as conv from "../runtime/conv.ts";
import * as filetype from "./filetype.ts";

// Vectors are generated by ts/tools/gen-render-vectors from Go's real render package (build tag javascript).
interface Vectors {
  isFileExt: [string, number, number, boolean][];
}
const data: Vectors = JSON.parse(readFileSync(new URL("./testdata/render_vectors.json", import.meta.url), "utf8"));

test("isFileExt matches Go", () => {
  for (const [s, pos, length, out] of data.isFileExt) {
    assert.equal(filetype.isFileExt(pos, length, conv.RunesFromString(s)), out, "input " + JSON.stringify(s) + " pos " + pos);
  }
});

test("commonFileTypes has the 76 entries of the Go table", () => {
  assert.equal(filetype.commonFileTypes.length, 76);
  assert.equal(filetype.commonFileTypesLen, 76);
  assert.equal(filetype.maxCommonFileTypeLen, 10);
});
